const items = $input.all();

return items.map(item => {
  const email = item.json;

  // Lấy nội dung văn bản thuần từ Gmail
  const body = String(email.text ?? '');

  // Tìm URL
  const matches = body.match(/https?:\/\/[^\s<>"']+/gi) || [];

  // Loại bỏ dấu câu cuối URL và trùng lặp
  const urls = [...new Set(
    matches.map(url => url.replace(/[.,;!?)}\]]+$/g, ''))
  )];

  // Lấy domain

  const domains = [...new Set(
    urls.map(url => {
      const match = url.match(/^https?:\/\/([^/?#:]+)/i);

      return match
        ? match[1].toLowerCase().replace(/^www\./, '')
        : null;
    }).filter(Boolean)
  )];


  return {
    json: {
      ...email,
      debugTextLength: body.length,
      debugTextPreview: body,
      debugMatches: matches,
      urls,
      urlCount: urls.length,
      domains
    }
  };
});

