const inputItems = $input.all();
const email = $('Get a message').first().json;

const timestamp = new Date().toISOString();

// ==========================================
// EVENT DETECTION HELPERS
// ==========================================

const isFileItem = (item) =>
  item.event_type === 'phishing_file_analysis' ||
  Boolean(item.file_sha256 || item.file_name);

const isUrlItem = (item) =>
  item.event_type === 'phishing_url_analysis' ||
  Boolean(item.data?.attributes?.stats) ||
  Boolean(item.url || item.urls);

const isPlaceholderItem = (item) =>
  item.event_type === 'no_url' ||
  item.event_type === 'no_file';

// ==========================================
// CHECK ALL ITEMS IN THIS EMAIL EXECUTION
// ==========================================

const hasFileEvent = inputItems.some(
  ({ json }) => isFileItem(json ?? {})
);

const hasUrlEvent = inputItems.some(
  ({ json }) => isUrlItem(json ?? {})
);

const hasIocEvent = hasFileEvent || hasUrlEvent;

const firstPlaceholderIndex = inputItems.findIndex(
  ({ json }) => isPlaceholderItem(json ?? {})
);

// ==========================================
// BUILD WAZUH EVENTS
// ==========================================

const output = [];

for (let i = 0; i < inputItems.length; i++) {

  const item = inputItems[i].json ?? {};

  // ========================================
  // NORMALIZE EMAIL INFORMATION
  // ========================================

  const rawSender =
    item.sender ??
    email.from?.value?.[0]?.address ??
    email.from?.text ??
    '';

  const senderMatch = String(rawSender).match(/<([^>]+)>/);

  const sender = senderMatch
    ? senderMatch[1].trim()
    : String(rawSender).trim();

  const emailId = item.email_id ?? email.id ?? 'unknown';
  const subject = item.subject ?? email.subject ?? '';

  const isFile = isFileItem(item);
  const isUrl = isUrlItem(item);
  const isPlaceholder = isPlaceholderItem(item);

  let event;

  // ========================================
  // 1. FILE ANALYSIS
  // ========================================

  if (isFile) {

    event = {
      event_timestamp: timestamp,

      integration: 'n8n_phishing',
      event_type: 'phishing_file_analysis',

      event_id: `${emailId}::file::${item.file_sha256 ?? 'unknown'}`,

      email_id: emailId,
      subject,
      sender,

      file_present: true,

      file_name: item.file_name ?? '',
      file_sha256: item.file_sha256 ?? '',
      file_type: item.file_type ?? '',

      vt_malicious: Number(item.vt_malicious ?? 0),
      vt_suspicious: Number(item.vt_suspicious ?? 0),
      vt_harmless: Number(item.vt_harmless ?? 0),
      vt_undetected: Number(item.vt_undetected ?? 0),

      sigma_critical: Number(item.sigma_critical ?? 0),
      sigma_high: Number(item.sigma_high ?? 0),
      sigma_medium: Number(item.sigma_medium ?? 0),

      file_verdict: item.file_verdict ?? 'unknown',
      file_severity: item.file_severity ?? 'unknown',

      vt_tags: item.vt_tags ?? []
    };

  }

  // ========================================
  // 2. URL ANALYSIS
  // ========================================

  else if (isUrl) {

    // Get the URL corresponding to this input item
    let splitItem = {};

    try {
      splitItem = $('Split Out').itemMatching(i).json ?? {};
    } catch (error) {
      splitItem = {};
    }

    const rawUrl =
      item.url ??
      item.urls ??
      splitItem.urls ??
      splitItem.url ??
      '';

    const url = Array.isArray(rawUrl)
      ? String(rawUrl[0] ?? '').trim()
      : String(rawUrl).trim();

    if (!url) {
      throw new Error(`URL not found for input item ${i}`);
    }

    const stats = item.data?.attributes?.stats ?? {};

    const malicious = Number(stats.malicious ?? 0);
    const suspicious = Number(stats.suspicious ?? 0);
    const harmless = Number(stats.harmless ?? 0);
    const undetected = Number(stats.undetected ?? 0);

    const match = url.match(/^https?:\/\/([^/:?#]+)/i);

    const domain = match
      ? match[1].toLowerCase()
      : '';

    const verdict =
      malicious > 0 ? 'malicious' :
      suspicious > 0 ? 'suspicious' :
      'clean';

    event = {
      event_timestamp: timestamp,

      integration: 'n8n_phishing',
      event_type: 'phishing_url_analysis',

      event_id: `${emailId}::${url}`,

      email_id: emailId,
      subject,
      sender,

      url_present: true,

      url,
      domain,

      vt_malicious: malicious,
      vt_suspicious: suspicious,
      vt_harmless: harmless,
      vt_undetected: undetected,

      verdict
    };

  }

  // ========================================
  // 3. NO URL / NO FILE
  // ========================================

  else if (isPlaceholder) {

    // If ANY URL or file IOC exists,
    // do not create email_no_ioc.
    if (hasIocEvent) {
      continue;
    }

    // If both no_url and no_file exist,
    // create only ONE no_ioc event.
    if (i !== firstPlaceholderIndex) {
      continue;
    }

    event = {
      event_timestamp: timestamp,

      integration: 'n8n_phishing',
      event_type: 'email_no_ioc',

      event_id: `${emailId}::no_ioc`,

      email_id: emailId,
      subject,
      sender,

      url_present: false,
      file_present: false,

      vt_malicious: 0,
      vt_suspicious: 0,
      vt_harmless: 0,
      vt_undetected: 0,

      verdict: 'no_ioc'
    };

  }

  // ========================================
  // 4. UNKNOWN EVENT
  // ========================================

  else {
    throw new Error(
      `Unknown event type: ${item.event_type ?? 'undefined'}`
    );
  }

  // ========================================
  // EMAIL TRACE / CORRELATION INFORMATION
  // ========================================

  const gmailMessageId = String(
    email.id ?? emailId ?? 'unknown'
  );

  const rawMessageId =
    email.messageId ??
    email.headers?.['message-id'] ??
    '';

  const internetMessageId = String(rawMessageId)
    .replace(/^Message-ID:\s*/i, '')
    .trim();

  event.email_id = gmailMessageId;
  event.message_id = internetMessageId;

  // ========================================
  // STANDARDIZED OUTPUT
  // ========================================

  const safeEmailId = String(emailId)
    .replace(/[^a-zA-Z0-9_-]/g, '_');

  const safeEventId = String(event.event_id ?? '')
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .slice(-80);

  output.push({
    json: {
      ...event,

      remote_file_name:
        `${safeEmailId}_${event.event_type}_${safeEventId}.json`,

      logLine: JSON.stringify(event) + '\n'
    },

    pairedItem: {
      item: i
    }
  });

}

return output;

// ==========================================
// CURRENT VIRUSTOTAL FILE REPORT
// ==========================================

const root = $json;
const attrs = root.data?.attributes ?? {};

const stats = attrs.last_analysis_stats ?? {};
const sigma = attrs.sigma_analysis_stats ?? {};

// ==========================================
// GET THE CORRECT PAIRED EMAIL
// IMPORTANT: DO NOT USE .first()
// ==========================================

const emailItem = $('Get a message').item;
const email = emailItem.json ?? {};

// Verify that this email actually has an attachment
const binaryEntries = Object.entries(emailItem.binary ?? {});

if (binaryEntries.length === 0) {
  throw new Error(
    `No attachment paired with email ${email.id ?? 'unknown'}. Refusing to create file event.`
  );
}

const [binaryKey, attachment] = binaryEntries[0];

// ==========================================
// VERIFY VIRUSTOTAL HASH AGAINST CRYPTO HASH
// ==========================================

const cryptoItem = $('Crypto').item;

const calculatedHash = String(
  cryptoItem.json?.sha256 ?? ''
).toLowerCase();

const reportHash = String(
  attrs.sha256 ?? root.data?.id ?? ''
).toLowerCase();

if (!reportHash) {
  throw new Error('VirusTotal report has no SHA256.');
}

if (
  calculatedHash &&
  calculatedHash !== reportHash
) {
  throw new Error(
    `SHA256 mismatch! Crypto: ${calculatedHash}, VirusTotal: ${reportHash}`
  );
}

// ==========================================
// EMAIL INFORMATION
// ==========================================

const rawSender =
  email.from?.value?.[0]?.address ??
  email.from?.text ??
  '';

const senderMatch = String(rawSender).match(/<([^>]+)>/);

const sender = senderMatch
  ? senderMatch[1].trim()
  : String(rawSender).trim();

const emailId = email.id ?? '';

if (!emailId) {
  throw new Error('Missing Gmail email ID.');
}

// ==========================================
// VIRUSTOTAL STATISTICS
// ==========================================

const malicious = Number(stats.malicious ?? 0);
const suspicious = Number(stats.suspicious ?? 0);

const sigmaCritical = Number(sigma.critical ?? 0);
const sigmaHigh = Number(sigma.high ?? 0);
const sigmaMedium = Number(sigma.medium ?? 0);

let fileVerdict = 'no_detection';
let fileSeverity = 'info';

if (malicious > 0) {
  fileVerdict = 'malicious';
  fileSeverity = 'critical';
} else if (
  suspicious > 0 ||
  sigmaCritical > 0 ||
  sigmaHigh > 0
) {
  fileVerdict = 'suspicious';
  fileSeverity = 'warning';
} else if (sigmaMedium > 0) {
  fileVerdict = 'review';
  fileSeverity = 'warning';
}

// ==========================================
// OUTPUT
// ==========================================

return {
  json: {
    event_type: 'phishing_file_analysis',

    email_id: emailId,
    subject: email.subject ?? '',
    sender,

    message_id: email.messageId ?? '',

    file_present: true,
    file_name:
      attachment.fileName ??
      attrs.meaningful_name ??
      attrs.names?.[0] ??
      'unknown',

    file_sha256: reportHash,
    file_type: attrs.type_description ?? '',

    vt_malicious: malicious,
    vt_suspicious: suspicious,
    vt_harmless: Number(stats.harmless ?? 0),
    vt_undetected: Number(stats.undetected ?? 0),

    sigma_critical: sigmaCritical,
    sigma_high: sigmaHigh,
    sigma_medium: sigmaMedium,
    sigma_low: Number(sigma.low ?? 0),

    file_verdict: fileVerdict,
    file_severity: fileSeverity,

    vt_tags: attrs.tags ?? []
  }
};
